// EDIT THESE. Sample values only. Do not put API tokens here.
const settings = {
  business_name: 'Sample Barber Shop',
  // Your GHL location (sub-account) ID. Leave as REPLACE_ME to skip the CRM write and only test parsing + dedupe.
  ghl_location_id: 'REPLACE_ME',
  ghl_api_url: 'https://services.leadconnectorhq.com/contacts/upsert',
  ghl_api_version: '2021-07-28',
  // Optional. If set, a short summary is POSTed here on a new call only (Slack or similar incoming webhook).
  owner_webhook_url: '',
  timezone: 'America/New_York',
  tag_new_call: 'end-of-call',
  tag_text_back: 'text-back-queued',
};

return $input.all().map(item => ({ json: { ...item.json, settings } }));

// Accepts a Vapi end-of-call-report, a Twilio status/hangup callback, or a simple test payload.
const item = $input.first().json;
const settings = item.settings;
const body = item.body !== undefined ? item.body : item;

const message = (body && body.message) ? body.message : body;
const msgType = message && message.type;

let source_provider = 'generic';
let call_id = '';
let caller_phone = '';
let dialed_number = '';
let caller_name = '';
let summary = '';

if (msgType === 'end-of-call-report' || (body && body.message && body.message.call)) {
  source_provider = 'vapi';
  const call = message.call || {};
  const customer = message.customer || call.customer || {};
  const phoneNumber = message.phoneNumber || {};
  const analysis = message.analysis || {};
  const structured = analysis.structuredData || {};
  call_id = call.id || '';
  caller_phone = customer.number || '';
  dialed_number = phoneNumber.number || '';
  caller_name = structured.name || customer.name || '';
  summary = analysis.summary || structured.summary || '';
} else if (body && (body.CallSid || body.call_session_id)) {
  source_provider = 'twilio';
  call_id = body.CallSid || body.call_session_id || '';
  caller_phone = body.From || body.from || '';
  dialed_number = body.To || body.to || '';
  caller_name = body.CallerName || body.caller_name || '';
  summary = body.CallStatus || body.event_type || '';
} else {
  call_id = body.call_id || body.callId || body.id || '';
  caller_phone = body.caller_phone || body.phone || '';
  dialed_number = body.dialed_number || body.to || '';
  caller_name = body.caller_name || body.name || '';
  summary = body.summary || '';
}

const missing = [];
if (!call_id) missing.push('call_id');
if (!caller_phone) missing.push('caller_phone');

return [{
  json: {
    settings,
    source_provider,
    event_type: msgType || body.CallStatus || 'test',
    call_id,
    caller_phone,
    dialed_number,
    caller_name,
    summary,
    valid: missing.length === 0,
    missing_fields: missing,
    raw_preview: JSON.stringify(body).slice(0, 500),
  }
}];

// Remembers call IDs in this workflow's static data.
// This only persists while the workflow is Active, not during a one-off manual test.
const item = $input.first().json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.seen_calls) staticData.seen_calls = {};

const now = Date.now();
const maxAgeMs = 7 * 24 * 60 * 60 * 1000;
for (const [id, ts] of Object.entries(staticData.seen_calls)) {
  if (now - ts > maxAgeMs) delete staticData.seen_calls[id];
}

// Cap the list so it cannot grow forever.
const ids = Object.keys(staticData.seen_calls);
if (ids.length > 500) {
  ids.sort((a, b) => staticData.seen_calls[a] - staticData.seen_calls[b]);
  for (const id of ids.slice(0, ids.length - 500)) delete staticData.seen_calls[id];
}

let is_duplicate = false;
let skip_reason = '';

if (!item.valid) {
  skip_reason = 'missing ' + item.missing_fields.join(', ');
} else if (staticData.seen_calls[item.call_id]) {
  is_duplicate = true;
  skip_reason = 'call_id already processed';
} else {
  staticData.seen_calls[item.call_id] = now;
}

return [{
  json: {
    ...item,
    is_duplicate,
    skip_reason,
    write_to_ghl: !is_duplicate && item.valid && item.settings.ghl_location_id && item.settings.ghl_location_id !== 'REPLACE_ME',
    notify_owner: !is_duplicate && item.valid && !!(item.settings.owner_webhook_url),
  }
}];
